import{az as s,P as l,Q as e,aQ as t}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const y=JSON.parse('{"title":"Virtual DOM","description":"","frontmatter":{},"headers":[],"relativePath":"框架/react/react/虚拟DOM.md","filePath":"框架/react/react/虚拟DOM.md","lastUpdated":1785246304000}'),n={name:"框架/react/react/虚拟DOM.md"};function o(p,a,r,c,D,i){return l(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="virtual-dom" tabindex="-1">Virtual DOM <a class="header-anchor" href="#virtual-dom" aria-label="Permalink to “Virtual DOM”">​</a></h1><p>Virtual DOM 是 React 用来描述 UI 的 JavaScript 对象树。组件返回的不是直接 DOM，而是这棵「虚拟树」。</p><h2 id="jsx-与-createelement" tabindex="-1">JSX 与 createElement <a class="header-anchor" href="#jsx-与-createelement" aria-label="Permalink to “JSX 与 createElement”">​</a></h2><p>JSX 最终会转成 <code>React.createElement</code>：</p><div class="language-jsx"><button title="Copy Code" class="copy"></button><span class="lang">jsx</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#C792EA;">const</span><span style="color:#BABED8;"> element </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;"> &lt;</span><span style="color:#F07178;">h1</span><span style="color:#C792EA;"> className</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">title</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">hello</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">h1</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;">// 约等于</span></span>
<span class="line"><span style="color:#BABED8;">React</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">createElement</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">h1</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#89DDFF;"> {</span><span style="color:#F07178;"> className</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">title</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;"> },</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">hello</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">)</span></span></code></pre></div><p>得到的大致形态：</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki material-theme-palenight" style="background-color:#292D3E;color:#babed8;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#FFCB6B;">  type</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">h1</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#FFCB6B;">  props</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> {</span></span>
<span class="line"><span style="color:#FFCB6B;">    className</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">title</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span></span>
<span class="line"><span style="color:#FFCB6B;">    children</span><span style="color:#89DDFF;">:</span><span style="color:#89DDFF;"> &#39;</span><span style="color:#C3E88D;">hello</span><span style="color:#89DDFF;">&#39;</span></span>
<span class="line"><span style="color:#89DDFF;">  }</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span></code></pre></div><p>组件同理：<code>type</code> 可以是函数 / 类，而不只是 HTML 标签名。</p><h2 id="为什么需要" tabindex="-1">为什么需要 <a class="header-anchor" href="#为什么需要" aria-label="Permalink to “为什么需要”">​</a></h2><p>直接命令式改 DOM 成本高、难维护。Virtual DOM 带来：</p><ul><li><strong>声明式</strong>：描述「UI 应该是什么」，而不是「怎么改 DOM」</li><li><strong>可对比</strong>：新旧两棵树 Diff 后，只更新真正变化的部分</li><li><strong>可跨环境</strong>：同一套描述可落到浏览器 DOM、或服务端 HTML 字符串</li></ul><h2 id="和真实-dom-的关系" tabindex="-1">和真实 DOM 的关系 <a class="header-anchor" href="#和真实-dom-的关系" aria-label="Permalink to “和真实 DOM 的关系”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Virtual DOM</th><th>真实 DOM</th></tr></thead><tbody><tr><td>本质</td><td>JS 对象</td><td>浏览器原生节点</td></tr><tr><td>创建 / 对比成本</td><td>相对便宜</td><td>相对昂贵</td></tr><tr><td>谁使用</td><td>React 内部协调</td><td>最终呈现给用户</td></tr></tbody></table><p>React 并不是「每次都全量重建 DOM」，而是用 Virtual DOM 算出最小变更，再在 <a href="./双阶段">Commit 阶段</a> 落到真实 DOM。</p><h2 id="和-fiber-的关系" tabindex="-1">和 Fiber 的关系 <a class="header-anchor" href="#和-fiber-的关系" aria-label="Permalink to “和 Fiber 的关系”">​</a></h2><p>早期 React 的协调更接近「递归对比 Virtual DOM」。引入 <a href="./fiber">Fiber</a> 后：</p><ul><li>对外仍可理解为 Virtual DOM / 元素树</li><li>对内真正被调度、遍历的是 Fiber 树</li></ul><p>Virtual DOM（React Element）更像「本次渲染的输入快照」，Fiber 才是可持续更新的工作单元。</p><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>Virtual DOM = UI 的轻量描述；真实 DOM = 最终画面。React 用前者算差异，再谨慎地改后者。</p>`,20)])])}const h=s(n,[["render",o]]);export{y as __pageData,h as default};
